import { useEffect, useMemo, useRef, useState } from "react";
import { useLocation } from "wouter";
import { trpc } from "@/lib/trpc";
import { EMPTY_PLANNER_STATE, PlannerState, BellPeriod, GradingTask, MonthlyEntry, ParentContact, PlannerClass, StudentNote, getLinkedStudentName } from "@shared/types";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import { toast } from "sonner";
import { ArrowRight, Check, ChevronLeft, ChevronRight, CircleHelp, Clock3, Command, FileText, Flag, LayoutDashboard, Plus, Save, Sparkles, Target, Trash2, Users, Zap } from "lucide-react";

const accentColors = ["#2F6F68", "#A6583D", "#B17A31", "#557A9A", "#7B608C", "#4E7C55", "#9B5E83", "#8D6B43"];
const weekDays = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"];
const statusCodes: GradingTask["status"][] = ["Collected", "Missing", "Late", "Reviewed", "Returned"];
const uid = () => (typeof crypto !== "undefined" && crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`);
const isoToday = () => new Date().toISOString().slice(0, 10);
const blankClasses = (): PlannerClass[] => Array.from({ length: 8 }, (_, index) => ({ id: `class-${index + 1}`, name: "", room: "", color: accentColors[index], members: [] }));
const normalizeClasses = (classes: PlannerClass[]) => Array.from({ length: 8 }, (_, index) => { const classId = classes[index]?.id ?? `class-${index + 1}`; const rawMembers = ((classes[index]?.members ?? []) as unknown) as Array<string | { id: string; name: string }>; return { id: classId, name: classes[index]?.name ?? "", room: classes[index]?.room ?? "", color: classes[index]?.color ?? accentColors[index], members: rawMembers.map((member, memberIndex) => typeof member === "string" ? { id: `${classId}-member-${memberIndex + 1}`, name: member } : member) }; });
const freshState = (): PlannerState => ({ ...EMPTY_PLANNER_STATE, identity: { ...EMPTY_PLANNER_STATE.identity, classes: blankClasses() } });

function FieldLabel({ children }: { children: React.ReactNode }) {
  return <label className="text-[11px] font-semibold uppercase tracking-[0.16em] text-muted-foreground">{children}</label>;
}
function SectionIntro({ eyebrow, title, description }: { eyebrow: string; title: string; description: string }) {
  return <div className="section-intro mb-7"><div className="max-w-3xl"><p className="eyebrow">{eyebrow}</p><h1 className="mt-2 text-3xl font-semibold tracking-[-0.04em] text-foreground md:text-4xl">{title}</h1><p className="mt-3 text-sm leading-6 text-muted-foreground">{description}</p></div><div className="section-signature"><span>focus page</span><strong>one clear<br />next step</strong></div></div>;
}
function EmptyState({ title, detail }: { title: string; detail: string }) {
  return <div className="rounded-2xl border border-dashed border-border bg-card/50 px-6 py-10 text-center"><CircleHelp className="mx-auto h-6 w-6 text-primary" /><p className="mt-3 font-medium">{title}</p><p className="mx-auto mt-1 max-w-md text-sm text-muted-foreground">{detail}</p></div>;
}

export default function Home() {
  const [location, setLocation] = useLocation();
  const section = new URLSearchParams(window.location.search).get("section") ?? "overview";
  const plannerQuery = trpc.planner.get.useQuery();
  const saveMutation = trpc.planner.save.useMutation();
  const resetMutation = trpc.planner.reset.useMutation();
  const [state, setState] = useState<PlannerState>(freshState);
  const [hydrated, setHydrated] = useState(false);
  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (plannerQuery.data && !hydrated) {
      const incoming = plannerQuery.data as PlannerState;
      setState({ ...incoming, identity: { ...incoming.identity, classes: normalizeClasses(incoming.identity.classes.length ? incoming.identity.classes : blankClasses()) } });
      setHydrated(true);
    }
  }, [plannerQuery.data, hydrated]);

  useEffect(() => {
    if (!hydrated) return;
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(() => {
      saveMutation.mutate({ state }, { onError: () => toast.error("Could not save this change") });
    }, 900);
    return () => { if (saveTimer.current) clearTimeout(saveTimer.current); };
  }, [state, hydrated]);

  const update = (recipe: (draft: PlannerState) => void) => setState(previous => { const draft = structuredClone(previous); recipe(draft); return draft; });
  const saveNow = () => saveMutation.mutate({ state }, { onSuccess: () => toast.success("Planner saved"), onError: () => toast.error("Could not save the planner") });
  const reset = () => resetMutation.mutate(undefined, { onSuccess: () => { setState(freshState()); toast.success("Planner reset"); } });
  const activeClassNames = useMemo(() => state.identity.classes.filter(item => item.name.trim()), [state.identity.classes]);
  const currentDate = isoToday();

  if (plannerQuery.isError) return <div className="flex min-h-[70vh] items-center justify-center"><Card className="max-w-md"><CardContent className="p-8 text-center"><CircleHelp className="mx-auto h-8 w-8 text-destructive" /><h1 className="mt-4 text-xl font-semibold">Your planner could not be opened</h1><p className="mt-2 text-sm leading-6 text-muted-foreground">Refresh the page or try again in a moment. Your saved planner data has not been changed.</p><Button className="mt-5" onClick={() => plannerQuery.refetch()}>Try again</Button></CardContent></Card></div>;
  if (plannerQuery.isLoading || !hydrated) return <div className="flex min-h-[70vh] items-center justify-center"><div className="loading-orb"><Sparkles className="h-5 w-5" /></div></div>;

  return <div className="planner-shell">
    <header className="planner-topbar">
      <div><p className="eyebrow">Focused Teacher Journal</p><p className="text-sm text-muted-foreground">A quiet command center for the school day</p></div>
      <div className="flex items-center gap-2"><Badge variant="secondary" className="hidden sm:flex"><span className="status-dot mr-2" />Autosaving</Badge><Button size="sm" onClick={saveNow} className="gap-2"><Save className="h-3.5 w-3.5" />Save now</Button></div>
    </header>
    <main className="planner-content">
      {section === "overview" && <Overview state={state} activeClasses={activeClassNames} onNavigate={(target) => setLocation(`/?section=${target}`)} currentDate={currentDate} />}
      {section === "setup" && <Setup state={state} update={update} />}
      {section === "bell" && <BellSchedule state={state} update={update} />}
      {section === "month" && <MonthlySpread state={state} update={update} />}
      {section === "week" && <WeeklyCommand state={state} update={update} />}
      {section === "daily" && <DailyPage state={state} update={update} />}
      {section === "grading" && <GradingTracker state={state} update={update} />}
      {section === "students" && <StudentNotes state={state} update={update} />}
      {section === "parents" && <ParentContacts state={state} update={update} />}
      {section === "procedures" && <Procedures state={state} update={update} />}
      {section === "supplementary" && <Supplementary state={state} update={update} />}
      <footer className="mt-10 flex flex-wrap items-center justify-between gap-3 border-t border-border/70 pt-5 text-xs text-muted-foreground"><span>Keep it light: capture what helps you decide, remember, support, or follow up.</span><button onClick={reset} className="hover:text-destructive">Reset planner data</button></footer>
    </main>
  </div>;
}

function Overview({ state, activeClasses, onNavigate, currentDate }: { state: PlannerState; activeClasses: PlannerClass[]; onNavigate: (section: string) => void; currentDate: string }) {
  const today = state.dailyEntries[currentDate];
  const upcoming = state.monthlyEntries.filter(entry => entry.date >= currentDate).sort((a, b) => a.date.localeCompare(b.date)).slice(0, 4);
  const periods = state.bellSchedule.filter(period => period.classId || period.start);
  return <>
    <section className="hero-panel"><div><p className="eyebrow">{state.identity.term || "New term"} · {state.identity.year || "Set your year"}</p><h1 className="mt-3 max-w-2xl text-4xl font-semibold tracking-[-0.05em] text-balance md:text-6xl">Make space for the next right thing.</h1><p className="mt-5 max-w-xl text-base leading-7 text-muted-foreground">A refined planner for planning less noisily, noticing more clearly, and returning to your work without starting over.</p><div className="mt-7 flex flex-wrap gap-3"><Button onClick={() => onNavigate("daily")} className="gap-2">Open today <ArrowRight className="h-4 w-4" /></Button><Button variant="outline" onClick={() => onNavigate("setup")}>Complete setup</Button></div></div><div className="hero-mark"><div className="hero-mark-inner"><Command className="h-7 w-7" /><span>one clear next step</span></div></div></section>
    <div className="mt-7 grid gap-4 md:grid-cols-3"><Card className="metric-card"><CardContent className="p-5"><p className="eyebrow">Today</p><p className="mt-3 text-3xl font-semibold">{periods.length || 0}</p><p className="mt-1 text-sm text-muted-foreground">lessons in your bell schedule</p></CardContent></Card><Card className="metric-card"><CardContent className="p-5"><p className="eyebrow">Classes</p><p className="mt-3 text-3xl font-semibold">{activeClasses.length}<span className="text-base text-muted-foreground"> / 8</span></p><p className="mt-1 text-sm text-muted-foreground">class spaces configured</p></CardContent></Card><Card className="metric-card"><CardContent className="p-5"><p className="eyebrow">Daily reflection</p><p className="mt-3 text-3xl font-semibold">{today?.notice || today?.adjust || today?.close ? "Saved" : "Open"}</p><p className="mt-1 text-sm text-muted-foreground">Notice · Adjust · Close</p></CardContent></Card></div>
    <div className="mt-8 grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><Card><CardHeader className="flex-row items-center justify-between"><div><p className="eyebrow">Today at a glance</p><CardTitle className="mt-1">{new Date(`${currentDate}T12:00:00`).toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" })}</CardTitle></div><Button variant="ghost" size="sm" onClick={() => onNavigate("daily")}>Daily page <ArrowRight className="ml-1 h-4 w-4" /></Button></CardHeader><CardContent>{periods.length ? <div className="schedule-list">{periods.slice(0, 6).map(period => <div className="schedule-row" key={period.id}><span className="time-pill">{period.start || "—"}<br /><span>{period.end || "—"}</span></span><div><p className="font-medium">{state.identity.classes.find(item => item.id === period.classId)?.name || "Unassigned class"}</p><p className="text-xs text-muted-foreground">{period.label || "Period"} · {period.room || "Room TBD"}</p></div><span className="ml-auto text-xs text-muted-foreground">{period.transitionNote || "No transition note"}</span></div>)}</div> : <EmptyState title="Your schedule is waiting" detail="Configure bell periods once, then they will appear here every school day." />}</CardContent></Card><Card><CardHeader><p className="eyebrow">Coming up</p><CardTitle className="mt-1">Small things, visible early</CardTitle></CardHeader><CardContent>{upcoming.length ? <div className="space-y-4">{upcoming.map(entry => <div key={entry.id} className="flex gap-3"><span className={`kind-dot ${entry.kind}`} /><div><p className="text-sm font-medium">{entry.title}</p><p className="text-xs text-muted-foreground">{entry.date} · {entry.kind}</p></div></div>)}</div> : <p className="text-sm leading-6 text-muted-foreground">Add deadlines, holidays, or extra tasks in the monthly spread to keep them in view without cluttering today.</p>}</CardContent></Card></div>
  </>;
}

function Setup({ state, update }: { state: PlannerState; update: (recipe: (draft: PlannerState) => void) => void }) {
  const [, setLocation] = useLocation();
  const [selectedClassId, setSelectedClassId] = useState(state.identity.classes.find(item => item.name.trim())?.id ?? state.identity.classes[0]?.id ?? "");
  const selectedClass = state.identity.classes.find(item => item.id === selectedClassId) ?? state.identity.classes[0];
  const [memberName, setMemberName] = useState("");
  const addMember = () => { if (!selectedClass || !memberName.trim()) return; update(d => { const classItem = d.identity.classes.find(item => item.id === selectedClass.id); if (classItem && !classItem.members.some(member => member.name.toLowerCase() === memberName.trim().toLowerCase())) classItem.members.push({ id: uid(), name: memberName.trim() }); }); setMemberName(""); };
  const removeMember = (memberId: string) => update(d => { const classItem = d.identity.classes.find(item => item.id === selectedClass?.id); if (classItem) classItem.members = classItem.members.filter(item => item.id !== memberId); });
  return <><SectionIntro eyebrow="01 · Identity" title="Set the context once." description="Your identity and class list will follow you through every planner section. Click a class to open its member list; eight class spaces are always available." /><Card><CardContent className="grid gap-5 p-6 md:grid-cols-2"><div><FieldLabel>Teacher name</FieldLabel><Input className="mt-2" value={state.identity.teacherName} onChange={event => update(d => { d.identity.teacherName = event.target.value; })} placeholder="Your name" /></div><div><FieldLabel>Subject(s)</FieldLabel><Input className="mt-2" value={state.identity.subjects} onChange={event => update(d => { d.identity.subjects = event.target.value; })} placeholder="e.g. English Language Arts" /></div><div><FieldLabel>Current year</FieldLabel><Input className="mt-2" value={state.identity.year} onChange={event => update(d => { d.identity.year = event.target.value; })} placeholder="2026–27" /></div><div><FieldLabel>Current term</FieldLabel><Input className="mt-2" value={state.identity.term} onChange={event => update(d => { d.identity.term = event.target.value; })} placeholder="Term 1" /></div></CardContent></Card><div className="mt-6 flex items-end justify-between"><div><p className="eyebrow">Class list</p><h2 className="mt-1 text-xl font-semibold">Up to 8 classes</h2></div><Badge variant="outline">{state.identity.classes.filter(item => item.name.trim()).length} configured</Badge></div><div className="mt-4 grid gap-3 md:grid-cols-2">{state.identity.classes.slice(0, 8).map((classItem, index) => <Card key={classItem.id} className={`class-edit-card cursor-pointer ${selectedClassId === classItem.id ? "ring-2 ring-primary/35" : ""}`} onClick={() => setSelectedClassId(classItem.id)}><CardContent className="flex items-center gap-3 p-4"><span className="class-swatch" style={{ backgroundColor: classItem.color }} /><div className="flex-1"><p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-muted-foreground">Class {index + 1} · {classItem.members.length} members</p><Input className="mt-2" value={classItem.name} onClick={event => event.stopPropagation()} onChange={event => update(d => { d.identity.classes[index].name = event.target.value; })} placeholder={`Class ${index + 1} name`} /></div><div className="w-28"><FieldLabel>Room</FieldLabel><Input className="mt-2" value={classItem.room} onClick={event => event.stopPropagation()} onChange={event => update(d => { d.identity.classes[index].room = event.target.value; })} placeholder="Room" /></div><Users className="h-4 w-4 text-primary" /></CardContent></Card>)}</div>{selectedClass && <Card className="roster-panel mt-5"><CardHeader className="flex-row items-start justify-between"><div><p className="eyebrow">Selected class</p><CardTitle className="mt-1">{selectedClass.name || "Unnamed class"}</CardTitle><p className="mt-1 text-sm text-muted-foreground">Add the people in this class once; the list stays with the planner.</p></div><Badge variant="secondary">{selectedClass.members.length} members</Badge></CardHeader><CardContent><div className="flex flex-col gap-3 sm:flex-row"><Input value={memberName} onChange={event => setMemberName(event.target.value)} onKeyDown={event => { if (event.key === "Enter") addMember(); }} placeholder="Student name" /><Button onClick={addMember} className="gap-2"><Plus className="h-4 w-4" />Add member</Button></div>{selectedClass.members.length ? <div className="mt-5 grid gap-2 sm:grid-cols-2">{selectedClass.members.map(member => <div key={member.id} className="roster-member"><button type="button" className="roster-member-link" onClick={() => setLocation(`/?section=students&classId=${encodeURIComponent(selectedClass.id)}&memberId=${encodeURIComponent(member.id)}`)} title={`Open notes for ${member.name}`}>{member.name || "Unnamed member"}</button><Input value={member.name} aria-label={`Rename ${member.name}`} onClick={event => event.stopPropagation()} onChange={event => update(d => { const classItem = d.identity.classes.find(item => item.id === selectedClass.id); const rosterMember = classItem?.members.find(item => item.id === member.id); if (rosterMember) rosterMember.name = event.target.value; })} /><button onClick={() => removeMember(member.id)} className="icon-button" aria-label={`Remove ${member.name}`}><Trash2 className="h-4 w-4" /></button></div>)}</div> : <EmptyState title="No class members yet" detail="Add names above to build this class roster." />}</CardContent></Card>}</>;
}

function BellSchedule({ state, update }: { state: PlannerState; update: (recipe: (draft: PlannerState) => void) => void }) {
  const periods = state.bellSchedule.length ? state.bellSchedule : Array.from({ length: 8 }, (_, index) => ({ id: `period-${index + 1}`, label: `Period ${index + 1}`, start: "", end: "", classId: "", room: "", transitionNote: "" }));
  useEffect(() => { if (!state.bellSchedule.length) update(d => { d.bellSchedule = periods; }); }, []);
  return <><SectionIntro eyebrow="02 · Rhythm" title="Make the bell schedule do the remembering." description="Configure each period once. The schedule will surface on your overview and daily page, with room and transition notes close at hand." /><Card><CardContent className="p-0"><div className="schedule-editor-header"><span>Period</span><span>Time</span><span>Class</span><span>Room</span><span>Transition note</span></div>{periods.map((period, index) => <div className="schedule-editor-row" key={period.id}><Input value={period.label} onChange={event => update(d => { d.bellSchedule[index].label = event.target.value; })} /><div className="time-pair"><Input type="time" value={period.start} onChange={event => update(d => { d.bellSchedule[index].start = event.target.value; })} /><span>to</span><Input type="time" value={period.end} onChange={event => update(d => { d.bellSchedule[index].end = event.target.value; })} /></div><select value={period.classId} onChange={event => update(d => { d.bellSchedule[index].classId = event.target.value; })} className="planner-select"><option value="">Unassigned</option>{state.identity.classes.map(classItem => <option key={classItem.id} value={classItem.id}>{classItem.name || `Class ${state.identity.classes.indexOf(classItem) + 1}`}</option>)}</select><Input value={period.room} onChange={event => update(d => { d.bellSchedule[index].room = event.target.value; })} placeholder="Room" /><Input value={period.transitionNote} onChange={event => update(d => { d.bellSchedule[index].transitionNote = event.target.value; })} placeholder="Reset, move, collect..." /></div>)}</CardContent></Card></>;
}

function MonthlySpread({ state, update }: { state: PlannerState; update: (recipe: (draft: PlannerState) => void) => void }) {
  const [month, setMonth] = useState(new Date().toISOString().slice(0, 7));
  const [draft, setDraft] = useState({ date: `${month}-01`, classId: "", kind: "deadline" as MonthlyEntry["kind"], title: "", details: "" });
  const days = new Date(Number(month.slice(0, 4)), Number(month.slice(5, 7)), 0).getDate();
  const entries = state.monthlyEntries.filter(item => item.date.startsWith(month));
  const add = () => { if (!draft.title.trim()) return; update(d => { d.monthlyEntries.push({ ...draft, id: uid() }); }); setDraft({ ...draft, title: "", details: "" }); };
  return <><SectionIntro eyebrow="03 · Bird’s-eye view" title="See the whole month without zooming in too far." description="Every row is a day. Every class has a lane. Keep entries short enough to recognize at a glance." /><div className="toolbar-row"><div><FieldLabel>Month</FieldLabel><Input type="month" className="mt-2 w-44" value={month} onChange={event => { setMonth(event.target.value); setDraft(d => ({ ...d, date: `${event.target.value}-01` })); }} /></div><div className="text-right"><p className="eyebrow">Visible lanes</p><p className="mt-1 text-sm text-muted-foreground">{state.identity.classes.filter(item => item.name.trim()).length || 8} class spaces</p></div></div><Card className="mt-5 overflow-hidden"><div className="monthly-grid"><div className="month-day-head">DAY</div>{state.identity.classes.map((item, index) => <div key={item.id} className="month-class-head" style={{ borderTopColor: item.color }}>{item.name || `Class ${index + 1}`}</div>)}{Array.from({ length: days }, (_, index) => { const day = String(index + 1).padStart(2, "0"); const date = `${month}-${day}`; return <div className="month-row" key={date}><div className="month-date">{day}<span>{new Date(`${date}T12:00:00`).toLocaleDateString(undefined, { weekday: "short" })}</span></div>{state.identity.classes.map(classItem => { const itemEntries = entries.filter(entry => entry.date === date && entry.classId === classItem.id); return <div className="month-cell" key={classItem.id}>{itemEntries.map(entry => <div className={`month-entry ${entry.kind}`} key={entry.id} title={entry.details}>{entry.title}</div>)}</div>; })}</div>; })}</div></Card><Card className="mt-5"><CardHeader><p className="eyebrow">Add to the month</p><CardTitle className="mt-1 text-lg">One small entry at a time</CardTitle></CardHeader><CardContent className="grid gap-3 md:grid-cols-[1fr_1.1fr_1fr_1.5fr_auto]"><Input type="date" value={draft.date} onChange={event => setDraft({ ...draft, date: event.target.value })} /><select className="planner-select" value={draft.classId} onChange={event => setDraft({ ...draft, classId: event.target.value })}><option value="">All classes / shared</option>{state.identity.classes.map((item, index) => <option key={item.id} value={item.id}>{item.name || `Class ${index + 1}`}</option>)}</select><select className="planner-select" value={draft.kind} onChange={event => setDraft({ ...draft, kind: event.target.value as MonthlyEntry["kind"] })}><option value="deadline">Deadline</option><option value="holiday">Holiday</option><option value="task">Extra task</option></select><Input placeholder="Short title" value={draft.title} onChange={event => setDraft({ ...draft, title: event.target.value })} /><Button onClick={add} className="gap-2"><Plus className="h-4 w-4" />Add</Button></CardContent></Card></>;
}

function WeeklyCommand({ state, update }: { state: PlannerState; update: (recipe: (draft: PlannerState) => void) => void }) {
  const [weekOf, setWeekOf] = useState(new Date().toISOString().slice(0, 10));
  const plan = state.weeklyPlans[weekOf] ?? { weekOf, priorities: ["", "", ""], days: Object.fromEntries(weekDays.map(day => [day, { lessonPrep: "", studentFollowUp: "", grading: "", meetings: "", nextStep: "" }])) };
  const setPlan = (recipe: (draft: typeof plan) => void) => update(d => { const next = structuredClone(plan); recipe(next); d.weeklyPlans[weekOf] = next; });
  return <><SectionIntro eyebrow="04 · Command center" title="Give the week one clear center of gravity." description="Choose the big three, then let each day hold only the details needed to move the week forward." /><div className="toolbar-row"><div><FieldLabel>Week of</FieldLabel><Input type="date" className="mt-2 w-44" value={weekOf} onChange={event => setWeekOf(event.target.value)} /></div><Badge variant="secondary" className="gap-2"><Target className="h-3.5 w-3.5" />Keep it to three priorities</Badge></div><Card className="mt-5"><CardHeader><p className="eyebrow">The big three</p><CardTitle className="mt-1 text-lg">What deserves your first attention?</CardTitle></CardHeader><CardContent className="grid gap-3 md:grid-cols-3">{plan.priorities.map((priority, index) => <div key={index} className="priority-input"><span>{index + 1}</span><Input value={priority} onChange={event => setPlan(d => { d.priorities[index] = event.target.value; })} placeholder="A meaningful outcome" /></div>)}</CardContent></Card><Card className="mt-5 overflow-hidden"><CardHeader><p className="eyebrow">Five-day view</p><CardTitle className="mt-1 text-lg">Plan only what helps you return</CardTitle></CardHeader><CardContent className="p-0"><div className="weekly-table-header"><span>DAY</span><span>LESSON / PREP</span><span>STUDENT FOLLOW-UP</span><span>GRADING</span><span>MEETINGS / TASKS</span><span>ONE NEXT STEP</span></div>{weekDays.map(day => <div className="weekly-row" key={day}><strong>{day.slice(0, 3).toUpperCase()}</strong><Textarea value={plan.days[day].lessonPrep} onChange={event => setPlan(d => { d.days[day].lessonPrep = event.target.value; })} placeholder="Lesson or prep" /><Textarea value={plan.days[day].studentFollowUp} onChange={event => setPlan(d => { d.days[day].studentFollowUp = event.target.value; })} placeholder="Student follow-up" /><Textarea value={plan.days[day].grading} onChange={event => setPlan(d => { d.days[day].grading = event.target.value; })} placeholder="Grade" /><Textarea value={plan.days[day].meetings} onChange={event => setPlan(d => { d.days[day].meetings = event.target.value; })} placeholder="Meetings / tasks" /><Textarea value={plan.days[day].nextStep} onChange={event => setPlan(d => { d.days[day].nextStep = event.target.value; })} placeholder="Next visible action" /></div>)}</CardContent></Card></>;
}

function DailyPage({ state, update }: { state: PlannerState; update: (recipe: (draft: PlannerState) => void) => void }) {
  const [date, setDate] = useState(isoToday());
  const entry = state.dailyEntries[date] ?? { date, energy: "", quickCapture: "", notice: "", adjust: "", close: "" };
  const updateEntry = (key: keyof typeof entry, value: string) => update(d => { const current = d.dailyEntries[date] ?? { date, energy: "", quickCapture: "", notice: "", adjust: "", close: "" }; (current as Record<string, string>)[key] = value; d.dailyEntries[date] = current; });
  return <><SectionIntro eyebrow="05 · Daily page" title="Return to the day without starting over." description="One entry per date. Keep notes quick, reflections guided, and your next action visible." /><div className="toolbar-row"><div className="flex items-end gap-3"><div><FieldLabel>Date</FieldLabel><Input type="date" className="mt-2 w-44" value={date} onChange={event => setDate(event.target.value)} /></div><Button variant="outline" size="icon" onClick={() => setDate(isoToday())} aria-label="Go to today"><Zap className="h-4 w-4" /></Button></div><div className="energy-check"><span className="eyebrow">Energy</span>{(["low", "steady", "high"] as const).map(item => <button key={item} onClick={() => updateEntry("energy", item)} className={entry.energy === item ? "energy-option active" : "energy-option"}>{item}</button>)}</div></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.05fr_.95fr]"><Card><CardHeader><p className="eyebrow">Schedule</p><CardTitle className="mt-1 text-lg">{new Date(`${date}T12:00:00`).toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" })}</CardTitle></CardHeader><CardContent>{state.bellSchedule.length ? <div className="schedule-list">{state.bellSchedule.map(period => <div className="schedule-row" key={period.id}><span className="time-pill">{period.start || "—"}<br /><span>{period.end || "—"}</span></span><div><p className="font-medium">{state.identity.classes.find(item => item.id === period.classId)?.name || "Unassigned"}</p><p className="text-xs text-muted-foreground">{period.label} · {period.room || "Room TBD"}</p></div><span className="ml-auto max-w-[12rem] text-right text-xs text-muted-foreground">{period.transitionNote}</span></div>)}</div> : <EmptyState title="Add your bell schedule first" detail="Once configured, every daily page will open with your actual lessons." />}</CardContent></Card><Card><CardHeader><p className="eyebrow">Quick capture</p><CardTitle className="mt-1 text-lg">Get it out of your head</CardTitle></CardHeader><CardContent><Textarea className="min-h-[230px]" value={entry.quickCapture} onChange={event => updateEntry("quickCapture", event.target.value)} placeholder="Names, ideas, materials, reminders, questions…" /></CardContent></Card></div><div className="mt-5 grid gap-4 md:grid-cols-3"><PromptCard label="Notice" prompt="What did students understand, need, or show today?" value={entry.notice} onChange={value => updateEntry("notice", value)} /><PromptCard label="Adjust" prompt="What is the smallest change that would help next time?" value={entry.adjust} onChange={value => updateEntry("adjust", value)} /><PromptCard label="Close" prompt="What can be released until tomorrow?" value={entry.close} onChange={value => updateEntry("close", value)} /></div></>;
}
function PromptCard({ label, prompt, value, onChange }: { label: string; prompt: string; value: string; onChange: (value: string) => void }) { return <Card className="prompt-card"><CardHeader><div className="flex items-center justify-between"><p className="eyebrow">{label}</p><span className="prompt-number">{label === "Notice" ? "01" : label === "Adjust" ? "02" : "03"}</span></div><CardTitle className="mt-1 text-base leading-6">{prompt}</CardTitle></CardHeader><CardContent><Textarea value={value} onChange={event => onChange(event.target.value)} placeholder="Write a few lines…" /></CardContent></Card>; }

function GradingTracker({ state, update }: { state: PlannerState; update: (recipe: (draft: PlannerState) => void) => void }) {
  const [draft, setDraft] = useState({ date: isoToday(), classId: "", task: "", status: "Collected" as GradingTask["status"], nextAction: "" });
  const add = () => { if (!draft.task.trim()) return; update(d => { d.gradingTasks.unshift({ ...draft, id: uid() }); }); setDraft({ ...draft, task: "", nextAction: "" }); };
  return <><SectionIntro eyebrow="06 · Grading" title="Make grading visible, not heavy." description="Use the exact status language to see what is collected, missing, late, reviewed, or returned—and keep one next action beside it." /><Card><CardContent className="grid gap-3 p-5 md:grid-cols-[1fr_1fr_1.4fr_1fr_1.5fr_auto]"><Input type="date" value={draft.date} onChange={event => setDraft({ ...draft, date: event.target.value })} /><select className="planner-select" value={draft.classId} onChange={event => setDraft({ ...draft, classId: event.target.value })}><option value="">Class</option>{state.identity.classes.map((item, index) => <option key={item.id} value={item.id}>{item.name || `Class ${index + 1}`}</option>)}</select><Input placeholder="Task / assessment" value={draft.task} onChange={event => setDraft({ ...draft, task: event.target.value })} /><select className="planner-select" value={draft.status} onChange={event => setDraft({ ...draft, status: event.target.value as GradingTask["status"] })}>{statusCodes.map(status => <option key={status}>{status}</option>)}</select><Input placeholder="Next action" value={draft.nextAction} onChange={event => setDraft({ ...draft, nextAction: event.target.value })} /><Button onClick={add}><Plus className="h-4 w-4" /></Button></CardContent></Card><Card className="mt-5 overflow-hidden"><CardContent className="p-0"><div className="data-table-header"><span>Date</span><span>Class</span><span>Task</span><span>Status</span><span>Next action</span><span /></div>{state.gradingTasks.length ? state.gradingTasks.map(task => <div className="data-table-row" key={task.id}><span>{task.date}</span><span>{state.identity.classes.find(item => item.id === task.classId)?.name || "Shared"}</span><span className="font-medium">{task.task}</span><Badge className={`status-badge ${task.status.toLowerCase()}`}>{task.status}</Badge><span className="text-muted-foreground">{task.nextAction || "—"}</span><button onClick={() => update(d => { d.gradingTasks = d.gradingTasks.filter(item => item.id !== task.id); })} className="icon-button"><Trash2 className="h-4 w-4" /></button></div>) : <div className="p-8"><EmptyState title="No grading tasks yet" detail="Add the next piece of grading, then keep its status and next action in view." /></div>}</CardContent></Card></>;
}

function StudentNotes({ state, update }: { state: PlannerState; update: (recipe: (draft: PlannerState) => void) => void }) {
  const [, setLocation] = useLocation();
  const params = new URLSearchParams(window.location.search);
  const individualClassId = params.get("classId") ?? "";
  const individualMemberId = params.get("memberId") ?? "";
  const individualClass = state.identity.classes.find(item => item.id === individualClassId);
  const individualMember = individualClass?.members.find(item => item.id === individualMemberId);
  const visibleNotes = individualMemberId
    ? state.studentNotes.filter(note => note.classId === individualClassId && note.rosterMemberId === individualMemberId)
    : state.studentNotes;
  const individualContacts = individualMemberId
    ? state.parentContacts.filter(contact => contact.classId === individualClassId && (contact.rosterMemberId === individualMemberId || (!contact.rosterMemberId && contact.student === individualMember?.name)))
    : [];
  const blank: Omit<StudentNote, "id"> = {
    name: individualMember?.name ?? "",
    classId: individualClassId,
    rosterMemberId: individualMemberId,
    strengths: "",
    evidence: "",
    supportNeeds: "",
    studentVoice: "",
    nextAction: "",
    reviewDate: "",
  };
  const [draft, setDraft] = useState(blank);
  const selectedMembers = state.identity.classes.find(item => item.id === draft.classId)?.members ?? [];
  const selectedRosterMember = selectedMembers.find(member => member.id === draft.rosterMemberId);
  const add = () => {
    if (!draft.name.trim() || !draft.rosterMemberId) return;
    update(d => {
      d.studentNotes.unshift({ ...draft, id: uid(), name: selectedRosterMember?.name ?? draft.name });
    });
    setDraft(blank);
  };
  return (
    <>
      <SectionIntro
        eyebrow="07 · Learners"
        title={individualMember ? `${individualMember.name}'s learner page.` : "Keep the whole learner in view."}
        description={individualMember ? `Notes and family context for ${individualMember.name} in ${individualClass?.name || "this class"}. Parent/carer details stay closed until you choose to open them.` : "Use factual, respectful notes that connect strengths, evidence, support needs, student voice, and the next review."}
      />
      <Card>
        <CardHeader><p className="eyebrow">New student or group note</p></CardHeader>
        <CardContent className="grid gap-3 md:grid-cols-2">
          <select className="planner-select" value={draft.classId} onChange={event => setDraft({ ...draft, classId: event.target.value, name: "", rosterMemberId: "" })}>
            <option value="">Class</option>
            {state.identity.classes.map((item, index) => <option key={item.id} value={item.id}>{item.name || `Class ${index + 1}`}</option>)}
          </select>
          <select className="planner-select" value={draft.rosterMemberId} onChange={event => { const member = selectedMembers.find(item => item.id === event.target.value); setDraft({ ...draft, rosterMemberId: event.target.value, name: member?.name ?? "" }); }} disabled={!draft.classId || selectedMembers.length === 0}>
            <option value="">Choose roster member</option>
            {selectedMembers.map(member => <option key={member.id} value={member.id}>{member.name}</option>)}
          </select>
          {(["strengths", "evidence", "supportNeeds", "studentVoice", "nextAction"] as const).map(key => <Textarea key={key} placeholder={{ strengths: "Strengths / interests / motivators", evidence: "Current learning evidence", supportNeeds: "Support needs / adaptations / extension", studentVoice: "Student voice / questions", nextAction: "Next action" }[key]} value={draft[key]} onChange={event => setDraft({ ...draft, [key]: event.target.value })} />)}
          <div className="flex gap-3"><Input type="date" value={draft.reviewDate} onChange={event => setDraft({ ...draft, reviewDate: event.target.value })} /><Button onClick={add} className="gap-2"><Plus className="h-4 w-4" />Add note</Button></div>
        </CardContent>
      </Card>
      <div className="mt-5 space-y-4">
        {visibleNotes.length ? visibleNotes.map(note => (
          <Card key={note.id}>
            <CardHeader className="flex-row items-start justify-between"><div><p className="eyebrow">{state.identity.classes.find(item => item.id === note.classId)?.name || "Shared"}</p><CardTitle className="mt-1 text-lg">{getLinkedStudentName(state, note)}</CardTitle></div><button onClick={() => update(d => { d.studentNotes = d.studentNotes.filter(item => item.id !== note.id); })} className="icon-button"><Trash2 className="h-4 w-4" /></button></CardHeader>
            {individualMember ? <CardContent className="grid gap-4 text-sm md:grid-cols-2"><Textarea placeholder="Strengths / interests / motivators" value={note.strengths} onChange={event => update(d => { const target = d.studentNotes.find(item => item.id === note.id); if (target) target.strengths = event.target.value; })} /><Textarea placeholder="Current learning evidence" value={note.evidence} onChange={event => update(d => { const target = d.studentNotes.find(item => item.id === note.id); if (target) target.evidence = event.target.value; })} /><Textarea placeholder="Support needs / adaptations / extension" value={note.supportNeeds} onChange={event => update(d => { const target = d.studentNotes.find(item => item.id === note.id); if (target) target.supportNeeds = event.target.value; })} /><Textarea placeholder="Student voice / questions" value={note.studentVoice} onChange={event => update(d => { const target = d.studentNotes.find(item => item.id === note.id); if (target) target.studentVoice = event.target.value; })} /><Textarea placeholder="Next action" value={note.nextAction} onChange={event => update(d => { const target = d.studentNotes.find(item => item.id === note.id); if (target) target.nextAction = event.target.value; })} /><Input type="date" value={note.reviewDate} onChange={event => update(d => { const target = d.studentNotes.find(item => item.id === note.id); if (target) target.reviewDate = event.target.value; })} /></CardContent> : <CardContent className="grid gap-4 text-sm md:grid-cols-2"><NoteBlock label="Strengths" value={note.strengths} /><NoteBlock label="Evidence" value={note.evidence} /><NoteBlock label="Support" value={note.supportNeeds} /><NoteBlock label="Student voice" value={note.studentVoice} /><NoteBlock label="Next action" value={note.nextAction} /><NoteBlock label="Review date" value={note.reviewDate || "Not set"} /></CardContent>}
          </Card>
        )) : <EmptyState title="No student notes yet" detail="Start with one student or group and keep the note grounded in what you saw and what you will do next." />}
      </div>
      {individualMember && (
        <details className="learner-contact-details mt-6">
          <summary><span><span className="eyebrow">Family context</span><strong>Parent / carer contacts</strong></span><span className="text-xs text-muted-foreground">Open details</span></summary>
          <div className="mt-4 space-y-3">
            {individualContacts.length ? individualContacts.map(contact => <div key={contact.id} className="contact-detail-row"><div><p className="eyebrow">{contact.date} · {contact.contact || "Contact route not set"}</p><p className="mt-1 text-sm font-medium">{contact.reason || "Reason not recorded"}</p></div><div className="text-sm text-muted-foreground"><p>{contact.summary || "No summary recorded."}</p><p className="mt-1">Agreement: {contact.agreement || "—"}{contact.followUpDate ? ` · Follow up ${contact.followUpDate}` : ""}</p></div></div>) : <p className="text-sm text-muted-foreground">No parent/carer contacts are linked to this learner yet.</p>}
            <Button variant="outline" size="sm" onClick={() => setLocation(`/?section=parents&classId=${encodeURIComponent(individualClass?.id ?? "")}&memberId=${encodeURIComponent(individualMember.id)}&student=${encodeURIComponent(individualMember.name)}`)}>Open full contact log</Button>
          </div>
        </details>
      )}
    </>
  );
}
function NoteBlock({ label, value }: { label: string; value: string }) { return <div className="note-block"><p className="eyebrow">{label}</p><p className="mt-2 whitespace-pre-wrap leading-6 text-muted-foreground">{value || "—"}</p></div>; }

function ParentContacts({ state, update }: { state: PlannerState; update: (recipe: (draft: PlannerState) => void) => void }) {
  const params = new URLSearchParams(window.location.search);
  const contextClassId = params.get("classId") ?? "";
  const contextStudent = params.get("student") ?? "";
  const contextMemberId = params.get("memberId") ?? "";
  const contextClass = state.identity.classes.find(item => item.id === contextClassId);
  const contextMember = contextClass?.members.find(member => member.id === contextMemberId) ?? contextClass?.members.find(member => member.name === contextStudent);
  const blank: Omit<ParentContact, "id"> = { student: contextMember?.name ?? contextStudent, classId: contextClassId, rosterMemberId: contextMemberId || contextMember?.id || "", date: isoToday(), contact: "", reason: "", summary: "", agreement: "", followUpDate: "" };
  const [draft, setDraft] = useState(blank);
  const add = () => { if (!draft.student.trim()) return; update(d => { d.parentContacts.unshift({ ...draft, id: uid() }); }); setDraft(blank); };
  return <><SectionIntro eyebrow="08 · Families" title="Keep communication warm, clear, and actionable." description="Record the reason, objective summary, agreement, and follow-up date so important conversations do not depend on memory." /><Card><CardContent className="grid gap-3 p-5 md:grid-cols-2"><Input placeholder="Student" value={draft.student} readOnly={Boolean(contextStudent)} onChange={event => setDraft({ ...draft, student: event.target.value })} /><select className="planner-select" value={draft.classId} onChange={event => setDraft({ ...draft, classId: event.target.value })}><option value="">Class</option>{state.identity.classes.map((item, index) => <option key={item.id} value={item.id}>{item.name || `Class ${index + 1}`}</option>)}</select><Input type="date" value={draft.date} onChange={event => setDraft({ ...draft, date: event.target.value })} /><Input placeholder="Parent / carer / contact route" value={draft.contact} onChange={event => setDraft({ ...draft, contact: event.target.value })} /><Textarea placeholder="Reason for contact" value={draft.reason} onChange={event => setDraft({ ...draft, reason: event.target.value })} /><Textarea placeholder="Summary" value={draft.summary} onChange={event => setDraft({ ...draft, summary: event.target.value })} /><Textarea placeholder="Agreement reached" value={draft.agreement} onChange={event => setDraft({ ...draft, agreement: event.target.value })} /><div className="flex gap-3"><Input type="date" value={draft.followUpDate} onChange={event => setDraft({ ...draft, followUpDate: event.target.value })} /><Button onClick={add} className="gap-2"><Plus className="h-4 w-4" />Log contact</Button></div></CardContent></Card><div className="mt-5 space-y-3">{state.parentContacts.length ? state.parentContacts.map(contact => <Card key={contact.id}><CardContent className="grid gap-4 p-5 md:grid-cols-[1fr_1fr_1.3fr_1.3fr_auto]"><div><p className="eyebrow">Student</p><p className="mt-1 font-medium">{contact.student}</p><p className="text-xs text-muted-foreground">{contact.date}</p></div><div><p className="eyebrow">Reason</p><p className="mt-1 text-sm text-muted-foreground">{contact.reason || "—"}</p></div><div><p className="eyebrow">Summary</p><p className="mt-1 text-sm text-muted-foreground">{contact.summary || "—"}</p></div><div><p className="eyebrow">Agreement / follow-up</p><p className="mt-1 text-sm text-muted-foreground">{contact.agreement || "—"} {contact.followUpDate ? `· ${contact.followUpDate}` : ""}</p></div><button onClick={() => update(d => { d.parentContacts = d.parentContacts.filter(item => item.id !== contact.id); })} className="icon-button"><Trash2 className="h-4 w-4" /></button></CardContent></Card>) : <EmptyState title="No parent contacts logged" detail="A short, factual record can make the next conversation calmer and easier to follow through." />}</div></>;
}

function Procedures({ state, update }: { state: PlannerState; update: (recipe: (draft: PlannerState) => void) => void }) {
  const procedureTitles = ["Fire / evacuation", "Lockdown / shelter", "Medical incident", "Safeguarding concern", "Behaviour escalation", "IT / building issue"];
  useEffect(() => { if (!state.procedures.length) update(d => { d.procedures = procedureTitles.map(title => ({ id: uid(), title, locationOrWho: "", steps: "" })); }); if (!state.importantContacts.length) update(d => { d.importantContacts = ["Emergency number", "School main office", "School lead / admin", "Nurse / counsellor / safeguarding"].map(label => ({ id: uid(), label, person: "", phone: "", notes: "" })); }); }, []);
  return <><SectionIntro eyebrow="09 · Safety" title="Keep the right details close at hand." description="Enter only the information you are authorized to store, and verify it against your school’s official procedures every year." /><Card><CardHeader><p className="eyebrow">Important contacts</p></CardHeader><CardContent className="grid gap-3 md:grid-cols-2">{state.importantContacts.map((contact, index) => <div className="contact-row" key={contact.id}><Input value={contact.label} onChange={event => update(d => { d.importantContacts[index].label = event.target.value; })} /><Input placeholder="Person / team" value={contact.person} onChange={event => update(d => { d.importantContacts[index].person = event.target.value; })} /><Input placeholder="Phone" value={contact.phone} onChange={event => update(d => { d.importantContacts[index].phone = event.target.value; })} /><Input placeholder="Notes" value={contact.notes} onChange={event => update(d => { d.importantContacts[index].notes = event.target.value; })} /></div>)}</CardContent></Card><div className="mt-5 grid gap-4 md:grid-cols-2">{state.procedures.map((procedure, index) => <Card key={procedure.id}><CardHeader><CardTitle className="text-base">{procedure.title}</CardTitle></CardHeader><CardContent className="space-y-3"><Input placeholder="Where / who" value={procedure.locationOrWho} onChange={event => update(d => { d.procedures[index].locationOrWho = event.target.value; })} /><Textarea className="min-h-[120px]" placeholder="Key steps / reminder" value={procedure.steps} onChange={event => update(d => { d.procedures[index].steps = event.target.value; })} /></CardContent></Card>)}</div></>;
}

function Supplementary({ state, update }: { state: PlannerState; update: (recipe: (draft: PlannerState) => void) => void }) {
  const [resource, setResource] = useState({ resource: "", topic: "", location: "" });
  const [meeting, setMeeting] = useState({ date: isoToday(), purpose: "", decision: "", ownerDate: "" });
  const [handover, setHandover] = useState({ date: isoToday(), essentials: "", routines: "", materials: "" });
  const [learning, setLearning] = useState({ date: isoToday(), topic: "", keyIdea: "", tryNext: "" });
  const [noteTitle, setNoteTitle] = useState(""); const [noteBody, setNoteBody] = useState("");
  const addNote = () => { if (!noteTitle.trim()) return; update(d => { d.supplementary.notes.unshift({ id: uid(), title: noteTitle, body: noteBody }); }); setNoteTitle(""); setNoteBody(""); };
  const addResource = () => { if (!resource.resource.trim()) return; update(d => { d.supplementary.resources.unshift({ id: uid(), ...resource }); }); setResource({ resource: "", topic: "", location: "" }); };
  const addMeeting = () => { if (!meeting.purpose.trim()) return; update(d => { d.supplementary.meetings.unshift({ id: uid(), ...meeting }); }); setMeeting({ date: isoToday(), purpose: "", decision: "", ownerDate: "" }); };
  const addHandover = () => { if (!handover.essentials.trim()) return; update(d => { d.supplementary.handovers.unshift({ id: uid(), ...handover }); }); setHandover({ date: isoToday(), essentials: "", routines: "", materials: "" }); };
  const addLearning = () => { if (!learning.topic.trim()) return; update(d => { d.supplementary.professionalLearning.unshift({ id: uid(), ...learning }); }); setLearning({ date: isoToday(), topic: "", keyIdea: "", tryNext: "" }); };
  return <><SectionIntro eyebrow="10 · Support pages" title="Keep the useful things one click away." description="These lightweight pages hold the recurring details that make the school day smoother: resources, meetings, handovers, professional learning, and free notes." /><div className="grid gap-5 md:grid-cols-2"><SupplementaryCard title="Resource index" fields={[{ placeholder: "Resource / link", value: resource.resource, set: (value: string) => setResource({ ...resource, resource: value }) }, { placeholder: "Topic / class", value: resource.topic, set: (value: string) => setResource({ ...resource, topic: value }) }, { placeholder: "Location", value: resource.location, set: (value: string) => setResource({ ...resource, location: value }) }]} onAdd={addResource} /><SupplementaryCard title="Meeting notes" fields={[{ placeholder: "Date", value: meeting.date, set: (value: string) => setMeeting({ ...meeting, date: value }) }, { placeholder: "Purpose", value: meeting.purpose, set: (value: string) => setMeeting({ ...meeting, purpose: value }) }, { placeholder: "Decision", value: meeting.decision, set: (value: string) => setMeeting({ ...meeting, decision: value }) }, { placeholder: "Owner / date", value: meeting.ownerDate, set: (value: string) => setMeeting({ ...meeting, ownerDate: value }) }]} onAdd={addMeeting} /><SupplementaryCard title="Substitute / handover" fields={[{ placeholder: "Date", value: handover.date, set: (value: string) => setHandover({ ...handover, date: value }) }, { placeholder: "Today’s essentials", value: handover.essentials, set: (value: string) => setHandover({ ...handover, essentials: value }) }, { placeholder: "Routine / safety", value: handover.routines, set: (value: string) => setHandover({ ...handover, routines: value }) }, { placeholder: "Where materials live", value: handover.materials, set: (value: string) => setHandover({ ...handover, materials: value }) }]} onAdd={addHandover} /><SupplementaryCard title="Professional learning" fields={[{ placeholder: "Date", value: learning.date, set: (value: string) => setLearning({ ...learning, date: value }) }, { placeholder: "Topic", value: learning.topic, set: (value: string) => setLearning({ ...learning, topic: value }) }, { placeholder: "Key idea", value: learning.keyIdea, set: (value: string) => setLearning({ ...learning, keyIdea: value }) }, { placeholder: "Try next", value: learning.tryNext, set: (value: string) => setLearning({ ...learning, tryNext: value }) }]} onAdd={addLearning} /></div><SupplementarySavedLists state={state} update={update} /><Card className="mt-5"><CardHeader><p className="eyebrow">Free notes</p><CardTitle className="mt-1 text-lg">Capture first. Sort later.</CardTitle></CardHeader><CardContent className="grid gap-3 md:grid-cols-[.7fr_1.3fr_auto]"><Input placeholder="Note title" value={noteTitle} onChange={event => setNoteTitle(event.target.value)} /><Input placeholder="Write a note, idea, or question" value={noteBody} onChange={event => setNoteBody(event.target.value)} /><Button onClick={addNote} className="gap-2"><Plus className="h-4 w-4" />Add</Button></CardContent></Card><div className="mt-4 space-y-3">{state.supplementary.notes.map(note => <Card key={note.id}><CardContent className="flex items-start justify-between gap-4 p-5"><div><p className="font-medium">{note.title}</p><p className="mt-1 whitespace-pre-wrap text-sm leading-6 text-muted-foreground">{note.body}</p></div><button onClick={() => update(d => { d.supplementary.notes = d.supplementary.notes.filter(item => item.id !== note.id); })} className="icon-button"><Trash2 className="h-4 w-4" /></button></CardContent></Card>)}</div></>;
}
function SupplementaryCard({ title, fields, onAdd }: { title: string; fields: { placeholder: string; value: string; set: (value: string) => void }[]; onAdd: () => void }) { return <Card><CardHeader><CardTitle className="text-base">{title}</CardTitle></CardHeader><CardContent className="space-y-3">{fields.map(field => <Input key={field.placeholder} placeholder={field.placeholder} value={field.value} onChange={event => field.set(event.target.value)} />)}<Button variant="outline" size="sm" onClick={onAdd} className="gap-2"><Check className="h-3.5 w-3.5" />Save entry</Button></CardContent></Card>; }
function SupplementarySavedLists({ state, update }: { state: PlannerState; update: (recipe: (draft: PlannerState) => void) => void }) {
  return <div className="mt-5 grid gap-4 md:grid-cols-2"><SavedList title="Saved resources" items={state.supplementary.resources.map(item => ({ id: item.id, title: item.resource, detail: `${item.topic || "No topic"} · ${item.location || "No location"}`, fields: [item.resource, item.topic, item.location], setField: (index: number, value: string) => update(d => { const row = d.supplementary.resources.find(entry => entry.id === item.id); if (!row) return; if (index === 0) row.resource = value; if (index === 1) row.topic = value; if (index === 2) row.location = value; }), remove: () => update(d => { d.supplementary.resources = d.supplementary.resources.filter(entry => entry.id !== item.id); }) }))} /><SavedList title="Saved meetings" items={state.supplementary.meetings.map(item => ({ id: item.id, title: item.purpose, detail: `${item.date} · ${item.decision || "No decision yet"}`, fields: [item.date, item.purpose, item.decision, item.ownerDate], setField: (index: number, value: string) => update(d => { const row = d.supplementary.meetings.find(entry => entry.id === item.id); if (!row) return; if (index === 0) row.date = value; if (index === 1) row.purpose = value; if (index === 2) row.decision = value; if (index === 3) row.ownerDate = value; }), remove: () => update(d => { d.supplementary.meetings = d.supplementary.meetings.filter(entry => entry.id !== item.id); }) }))} /><SavedList title="Saved handovers" items={state.supplementary.handovers.map(item => ({ id: item.id, title: item.essentials, detail: `${item.date} · ${item.routines || "No routine note"}`, fields: [item.date, item.essentials, item.routines, item.materials], setField: (index: number, value: string) => update(d => { const row = d.supplementary.handovers.find(entry => entry.id === item.id); if (!row) return; if (index === 0) row.date = value; if (index === 1) row.essentials = value; if (index === 2) row.routines = value; if (index === 3) row.materials = value; }), remove: () => update(d => { d.supplementary.handovers = d.supplementary.handovers.filter(entry => entry.id !== item.id); }) }))} /><SavedList title="Saved learning" items={state.supplementary.professionalLearning.map(item => ({ id: item.id, title: item.topic, detail: `${item.date} · ${item.tryNext || "No next step"}`, fields: [item.date, item.topic, item.keyIdea, item.tryNext], setField: (index: number, value: string) => update(d => { const row = d.supplementary.professionalLearning.find(entry => entry.id === item.id); if (!row) return; if (index === 0) row.date = value; if (index === 1) row.topic = value; if (index === 2) row.keyIdea = value; if (index === 3) row.tryNext = value; }), remove: () => update(d => { d.supplementary.professionalLearning = d.supplementary.professionalLearning.filter(entry => entry.id !== item.id); }) }))} /></div>;
}
function SavedList({ title, items }: { title: string; items: { id: string; title: string; detail: string; fields: string[]; setField: (index: number, value: string) => void; remove: () => void }[] }) { return <Card><CardHeader><CardTitle className="text-base">{title}</CardTitle></CardHeader><CardContent className="space-y-3">{items.length ? items.map(item => <div key={item.id} className="saved-entry"><div className="flex items-start justify-between gap-2"><div><p className="text-sm font-medium">{item.title || "Untitled entry"}</p><p className="text-xs text-muted-foreground">{item.detail}</p></div><button onClick={item.remove} className="icon-button"><Trash2 className="h-4 w-4" /></button></div><div className="grid gap-2">{item.fields.map((field, index) => <Input key={`${item.id}-${index}`} value={field} onChange={event => item.setField(index, event.target.value)} className="h-8 text-xs" />)}</div></div>) : <p className="text-sm text-muted-foreground">Nothing saved here yet.</p>}</CardContent></Card>; }
